#include <iostream>
#include <cmath>
#include <algorithm>

using namespace std;

int getDigitsCount(long long n) {
    return (int)log10(n) + 1;
}

long long generateSequence(int length) {
    long long val = 1;
    for (int i = 1; i < length; i++) {
        val = val * 10 + 1;
    }
    return val;
}

long long countOnes(long long n);

long long countOnesHelper(long long n) {
    if (n <= 6) return n;
    int digits = getDigitsCount(n);
    long long baseSeq = generateSequence(digits);
    long long sumSeq = baseSeq;
    int count = 0;
    long long diff = n;

    while (sumSeq < n) {
        count++;
        diff = n - sumSeq;
        sumSeq += generateSequence(digits);
    }

    long long res;
    if (count > 0)
        res = min(count * digits + countOnes(diff),
                  (count + 1) * digits + countOnes(sumSeq - n));
    else
        res = (count + 1) * digits + countOnes(sumSeq - n);

    long long nextSeq = generateSequence(digits + 1);
    if (nextSeq - n < n)
        res = min(res, digits + 1 + countOnes(nextSeq - n));
    return res;
}

long long countOnes(long long n) {
    return countOnesHelper(n);
}

int main() {
    long long input;
    cin >> input;
    cout << countOnes(input) << endl;
    return 0;
}
